import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, isWon, MOVES_MAX } from '../game.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { isAcceptedTournamentName } from './names.ts';
import { matchPlans } from './pairing.ts';
import { winningSeed } from './rules.ts';
import type { Entrant, Tournament, TournamentMatch, TournamentResult } from './rules.ts';

const EVENT_KEYS = [
  'kind', 'playerCount', 'players', 'matches', 'currentMatchIndex', 'currentTurn', 'phase',
  'createdAt', 'finishedAt', 'gameSnapshot', 'gameElapsedMs',
];
const MATCH_KEYS = [
  'round', 'number', 'size', 'boardCode', 'playerSeeds', 'results', 'winnerSeed', 'advanceTo',
];

export function serializeEvent(tournament: Tournament): Record<string, unknown> {
  return {
    kind: 'event',
    playerCount: tournament.playerCount,
    players: tournament.players,
    matches: tournament.matches,
    currentMatchIndex: tournament.currentMatchIndex,
    currentTurn: tournament.currentTurn,
    phase: tournament.phase,
    createdAt: tournament.createdAt,
    finishedAt: tournament.finishedAt,
    gameSnapshot: tournament.currentGame ? encodeSnapshot(tournament.currentGame) : null,
    gameElapsedMs: tournament.currentGame?.elapsedMs ?? null,
  };
}

export function parseEvent(value: unknown): Tournament | null {
  if (!isJsonObject(value) || !hasExactKeys(value, EVENT_KEYS) || value.kind !== 'event') return null;
  const count = value.playerCount;
  if (count !== 4 && count !== 8) return null;
  const players = readPlayers(value.players, count);
  const plans = matchPlans(count);
  const matches = readMatches(value.matches, plans, count);
  const currentMatchIndex = value.currentMatchIndex;
  const currentTurn = value.currentTurn;
  const phase = value.phase;
  if (
    !players || !matches || !isNonnegativeSafeInteger(currentMatchIndex) ||
    currentMatchIndex >= matches.length || (currentTurn !== 0 && currentTurn !== 1) ||
    !['ready', 'playing', 'turnComplete', 'finished'].includes(String(phase))
  ) return null;
  if (!isIsoDate(value.createdAt)) return null;
  const finishedAt = value.finishedAt;
  if (finishedAt !== null && !isIsoDate(finishedAt)) return null;
  const bracket = validateBracket(matches, plans, count);
  if (!bracket || !validProgress(matches, currentMatchIndex, currentTurn, phase, finishedAt)) return null;
  const currentMatch = matches[currentMatchIndex];
  if (!currentMatch) return null;
  const currentGame = readCurrentGame(
    value.gameSnapshot,
    value.gameElapsedMs,
    phase,
    currentMatch,
    matches[currentMatchIndex]?.results[currentTurn] ?? null,
  );
  if (currentGame === undefined) return null;
  return {
    playerCount: count,
    players,
    matches,
    currentMatchIndex,
    currentTurn,
    phase,
    currentGame,
    createdAt: value.createdAt,
    finishedAt,
  };
}

function readPlayers(value: unknown, count: 4 | 8): Entrant[] | null {
  if (!Array.isArray(value) || value.length !== count) return null;
  const players: Entrant[] = [];
  for (let index = 0; index < count; index += 1) {
    const item: unknown = value[index];
    if (!isJsonObject(item) || !hasExactKeys(item, ['seed', 'name'])) return null;
    if (item.seed !== index + 1 || typeof item.name !== 'string' || !isAcceptedTournamentName(item.name))
      return null;
    players.push({ seed: item.seed, name: item.name });
  }
  return new Set(players.map((player) => player.name.toLowerCase())).size === count ? players : null;
}

function readResult(value: unknown, size: number): TournamentResult | null | undefined {
  if (value === null) return null;
  if (!isJsonObject(value) || !hasExactKeys(value, ['moves', 'elapsedMs'])) return undefined;
  const { moves, elapsedMs } = value;
  if (
    !isNonnegativeSafeInteger(moves) || moves < (size * size) / 4 || moves > MOVES_MAX ||
    typeof elapsedMs !== 'number' || !Number.isFinite(elapsedMs) ||
    elapsedMs < 0 || elapsedMs > ELAPSED_MAX_MS
  ) return undefined;
  return { moves, elapsedMs };
}

function readMatches(value: unknown, plans: ReturnType<typeof matchPlans>, count: 4 | 8): TournamentMatch[] | null {
  if (!Array.isArray(value) || value.length !== plans.length) return null;
  const usedCodes = new Set<string>();
  const matches: TournamentMatch[] = [];
  for (let index = 0; index < plans.length; index += 1) {
    const item: unknown = value[index];
    const plan = plans[index];
    if (!plan || !isJsonObject(item) || !hasExactKeys(item, MATCH_KEYS)) return null;
    const parsedCode = typeof item.boardCode === 'string' ? parseBoardCode(item.boardCode) : null;
    if (
      item.round !== plan.round || item.number !== plan.number || item.size !== plan.size ||
      !parsedCode || parsedCode.size !== plan.size || usedCodes.has(item.boardCode as string)
    ) return null;
    usedCodes.add(item.boardCode as string);
    if (!Array.isArray(item.playerSeeds) || item.playerSeeds.length !== 2 ||
        !Array.isArray(item.results) || item.results.length !== 2) return null;
    const playerSeeds = item.playerSeeds;
    if (!playerSeeds.every((seed) => seed === null || (isNonnegativeSafeInteger(seed) && seed > 0 && seed <= count)))
      return null;
    const first = readResult(item.results[0], plan.size);
    const second = readResult(item.results[1], plan.size);
    if (first === undefined || second === undefined) return null;
    const advanceTo = readAdvance(item.advanceTo, plan.advanceTo);
    const winnerSeed = item.winnerSeed;
    if (advanceTo === undefined ||
        !(winnerSeed === null || (isNonnegativeSafeInteger(winnerSeed) && winnerSeed > 0 && winnerSeed <= count)))
      return null;
    matches.push({
      ...plan,
      boardCode: item.boardCode as string,
      playerSeeds: [playerSeeds[0] as number | null, playerSeeds[1] as number | null],
      results: [first, second],
      winnerSeed,
      advanceTo,
    });
  }
  return matches;
}

function readAdvance(
  value: unknown,
  expected: TournamentMatch['advanceTo'],
): TournamentMatch['advanceTo'] | undefined {
  if (expected === null) return value === null ? null : undefined;
  if (!isJsonObject(value) || !hasExactKeys(value, ['matchIndex', 'slot'])) return undefined;
  return value.matchIndex === expected.matchIndex && value.slot === expected.slot ? expected : undefined;
}

function validateBracket(
  matches: readonly TournamentMatch[],
  plans: ReturnType<typeof matchPlans>,
  count: 4 | 8,
): boolean {
  const expectedSeeds = plans.map((plan) => [...plan.playerSeeds] as [number | null, number | null]);
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const seeds = expectedSeeds[index];
    if (!match || !seeds || match.playerSeeds.some((seed, slot) => seed !== seeds[slot])) return false;
    const [first, second] = match.results;
    if (second && !first) return false;
    if (first && second) {
      const firstSeed = match.playerSeeds[0];
      const secondSeed = match.playerSeeds[1];
      if (firstSeed === null || secondSeed === null ||
          match.winnerSeed !== winningSeed(firstSeed, first, secondSeed, second)) return false;
      if (match.advanceTo) {
        const target = expectedSeeds[match.advanceTo.matchIndex];
        if (!target || target[match.advanceTo.slot] !== null) return false;
        target[match.advanceTo.slot] = match.winnerSeed;
      }
    } else if (match.winnerSeed !== null) return false;
  }
  return count === 4 || count === 8;
}

function validProgress(
  matches: readonly TournamentMatch[],
  index: number,
  turn: 0 | 1,
  phase: unknown,
  finishedAt: unknown,
): boolean {
  const active = matches[index];
  if (!active) return false;
  for (let before = 0; before < index; before += 1)
    if (!complete(matches[before])) return false;
  for (let after = index + 1; after < matches.length; after += 1)
    if (matches[after]?.results.some(Boolean)) return false;
  const [first, second] = active.results;
  if (phase === 'finished') return index === matches.length - 1 && complete(active) && finishedAt !== null;
  if (finishedAt !== null) return false;
  if (phase === 'ready' || phase === 'playing')
    return turn === 0 ? !first && !second : !!first && !second;
  if (phase === 'turnComplete')
    return turn === 0 ? !!first && !second : !!first && !!second && index < matches.length - 1;
  return false;
}

function complete(match: TournamentMatch | undefined): boolean {
  return !!match?.results[0] && !!match.results[1] && match.winnerSeed !== null;
}

function readCurrentGame(
  snapshot: unknown,
  elapsedMs: unknown,
  phase: unknown,
  match: TournamentMatch,
  result: TournamentResult | null,
) {
  const hasGame = phase === 'playing' || phase === 'turnComplete';
  if (!hasGame) return snapshot === null && elapsedMs === null ? null : undefined;
  if (typeof snapshot !== 'string' || typeof elapsedMs !== 'number' ||
      !Number.isFinite(elapsedMs) || elapsedMs < 0 || elapsedMs > ELAPSED_MAX_MS) return undefined;
  const decoded = decodeSnapshot(snapshot);
  if (!decoded || decoded.boardCode !== match.boardCode || elapsedMs < decoded.elapsedMs ||
      elapsedMs >= decoded.elapsedMs + 1) return undefined;
  const game = { ...decoded, elapsedMs };
  if (phase === 'playing' && isWon(game)) return undefined;
  if (phase === 'turnComplete' && (!isWon(game) || !result || result.moves !== game.moves || result.elapsedMs !== game.elapsedMs))
    return undefined;
  return game;
}

function isIsoDate(value: unknown): value is string {
  if (typeof value !== 'string') return false;
  const date = new Date(value);
  return Number.isFinite(date.getTime()) && date.toISOString() === value;
}

