import { useEffect, useRef, useState } from 'react';
import { activateCard, advanceGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from '../session/browser-clock.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { decodeTournamentFile, TOURNAMENT_HISTORY_LIMIT } from './format.ts';
import { matchPlans } from './pairing.ts';
import { beginTurn, createTournament, finishTurn, nextMatch, nextTurn } from './rules.ts';
import { browserTournamentStore, readTournamentHistory, writeTournamentHistory } from './storage.ts';
import type { Tournament } from './rules.ts';
import type { Entrant, PlayerCount } from './rules.ts';
import type { TournamentDraft, TournamentLoad } from './format.ts';

export const TournamentNotice = {
  invalid: 'Invalid tournament JSON.',
  loaded: 'Tournament loaded.',
  saved: 'Tournament saved in Past tournaments.',
} as const;

export function useTournament() {
  const [store] = useState(browserTournamentStore);
  const [initialHistory] = useState(() => readTournamentHistory(store));
  const [tournament, setTournament] = useState<Tournament | null>(null);
  const current = useRef(tournament);
  const past = useRef(initialHistory.tournaments);
  const [pastTournaments, setPastTournaments] = useState(initialHistory.tournaments);
  const [storageAvailable, setStorageAvailable] = useState(initialHistory.available);
  const [notice, setNotice] = useState('');
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);

  function recordCompleted(completed: Tournament): void {
    const code = completed.matches[0]?.boardCode ?? '';
    if (past.current.some((item) => item.createdAt === completed.createdAt && item.matches[0]?.boardCode === code))
      return;
    const next = [completed, ...past.current].slice(0, TOURNAMENT_HISTORY_LIMIT);
    past.current = next;
    setPastTournaments(next);
    if (!writeTournamentHistory(store, next)) setStorageAvailable(false);
  }

  function commit(next: Tournament | null): void {
    const previous = current.current;
    if (next === previous) return;
    current.current = next;
    setTournament(next);
    if (next?.phase === 'finished' && previous?.phase !== 'finished') {
      recordCompleted(next);
      setNotice(TournamentNotice.saved);
    }
  }

  function running(): boolean {
    const active = current.current;
    return visible.current && active?.phase === 'playing' &&
      !!active.currentGame?.started && !isWon(active.currentGame);
  }

  function synchronize(): void {
    const step = elapsedStep(clock.current, performance.now(), running());
    clock.current = step.clock;
    const active = current.current;
    if (!step.milliseconds || !active?.currentGame) return;
    commit({ ...active, currentGame: advanceGame(active.currentGame, step.milliseconds) });
  }

  useEffect(() => {
    const active = current.current;
    const generation = `${active?.currentMatchIndex ?? -1}:${active?.currentTurn ?? -1}:${active?.phase ?? 'setup'}`;
    let mounted = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      const value = current.current;
      if (!mounted || !running() || !value?.currentGame) return;
      const selection = value.currentGame.selection;
      const delay = selection.kind === SelectionKind.mismatch
        ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
        : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!mounted) return;
        synchronize();
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!mounted) return;
      synchronize();
      visible.current = !document.hidden;
      schedule();
    }
    void generation;
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      mounted = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [tournament?.currentMatchIndex, tournament?.currentTurn, tournament?.phase]);

  function startTournament(names: readonly string[], playerCount: PlayerCount): void {
    const players: Entrant[] = names.map((name, index) => ({ seed: index + 1, name }));
    const used = new Set<string>();
    const codes = matchPlans(playerCount).map((plan) => {
      let code = freshBoardCode(plan.size);
      while (used.has(code)) code = freshBoardCode(plan.size);
      used.add(code);
      return code;
    });
    clock.current = createClock(performance.now());
    setNotice('');
    commit(createTournament(players, codes, new Date().toISOString()));
  }

  function startTurn(): void {
    const active = current.current;
    if (!active) return;
    clock.current = createClock(performance.now());
    commit(beginTurn(active));
  }

  function activate(index: number): void {
    synchronize();
    const active = current.current;
    const game = active?.currentGame;
    if (!active || active.phase !== 'playing' || !game) return;
    const nextGame = activateCard(game, index);
    if (nextGame === game) return;
    if (isWon(nextGame))
      commit(finishTurn(active, nextGame, new Date().toISOString()));
    else commit({ ...active, currentGame: nextGame });
  }

  function advanceToNextTurn(): void {
    const active = current.current;
    if (!active) return;
    clock.current = createClock(performance.now());
    commit(nextTurn(active));
  }

  function advanceToNextMatch(): void {
    const active = current.current;
    if (!active) return;
    clock.current = createClock(performance.now());
    commit(nextMatch(active));
  }

  function loadTournament(text: string): TournamentLoad | null {
    const loaded = decodeTournamentFile(text);
    if (!loaded) {
      setNotice(TournamentNotice.invalid);
      return null;
    }
    clock.current = createClock(performance.now());
    setNotice(TournamentNotice.loaded);
    if (loaded.kind === 'setup') commit(null);
    else {
      commit(loaded.tournament);
      if (loaded.tournament.phase === 'finished') recordCompleted(loaded.tournament);
    }
    return loaded;
  }

  function exportTournament(draft: TournamentDraft): string {
    return import('./format.ts').then ? '' : '';
  }

  return {
    tournament,
