import { useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { normalizeTournamentName, validateTournamentNames } from './names.ts';
import { Bracket } from './Bracket.tsx';
import { currentMatch, currentPlayer, champion } from './rules.ts';
import { useTournament } from './use-tournament.ts';
import type { PlayerCount, Tournament } from './rules.ts';
import './tournament.css';

interface TournamentProps {
  onLeave(): void;
}

export function TournamentScreen({ onLeave }: TournamentProps) {
  const controller = useTournament();
  const [playerCount, setPlayerCount] = useState<PlayerCount>(4);
  const [names, setNames] = useState(() => Array<string>(8).fill(''));
  const [tournamentJson, setTournamentJson] = useState('');
  const [formError, setFormError] = useState('');
  const tournament = controller.tournament;
  const player = tournament && tournament.phase !== 'finished' ? currentPlayer(tournament) : null;
  const match = tournament && tournament.phase !== 'finished' ? currentMatch(tournament) : null;

  function start(event: React.FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const accepted = names.slice(0, playerCount).map(normalizeTournamentName);
    const error = validateTournamentNames(accepted);
    if (error) {
      setFormError(error);
      return;
    }
    const nextNames = [...names];
    accepted.forEach((name, index) => { nextNames[index] = name; });
    setNames(nextNames);
    setFormError('');
    controller.startTournament(accepted, playerCount);
  }

  function exportTournament(): void {
    setTournamentJson(controller.exportTournament({ playerCount, names }));
  }

  function loadTournament(): void {
    const loaded = controller.loadTournament(tournamentJson);
    if (loaded?.kind === 'setup') {
      setPlayerCount(loaded.draft.playerCount);
      setNames([...loaded.draft.names]);
      setFormError('');
    }
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <div className="tournament-heading-row">
        <h2 id="tournament-heading">Tournament</h2>
        {tournament?.phase !== 'finished' && (
          <button className="control" type="button" onClick={onLeave}>Leave tournament</button>
        )}
      </div>

      {tournament ? (
        <LiveTournament
          tournament={tournament}
          playerName={player?.name ?? ''}
          currentRound={match?.round ?? ''}
          startTurn={controller.startTurn}
          activate={controller.activate}
          nextTurn={controller.advanceToNextTurn}
          nextMatch={controller.advanceToNextMatch}
          onBack={onLeave}
        />
      ) : (
        <form className="tournament-setup" onSubmit={start}>
          <div className="tournament-player-count">
            <label htmlFor="tournament-player-count">Players</label>
            <select
              id="tournament-player-count"
              className="control"
              value={playerCount}
              onChange={(event) => setPlayerCount(Number(event.currentTarget.value) as PlayerCount)}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
          </div>
          <fieldset className="tournament-names">
            <legend>Enter player names</legend>
            {names.slice(0, playerCount).map((name, index) => (
              <div className="tournament-name-field" key={index}>
                <label htmlFor={`tournament-player-${index + 1}`}>Player {index + 1}</label>
                <input
                  id={`tournament-player-${index + 1}`}
                  className="control"
                  type="text"
                  autoComplete="off"
                  value={name}
                  onChange={(event) => {
                    const next = [...names];
                    next[index] = event.currentTarget.value;
                    setNames(next);
                    setFormError('');
                    controller.clearNotice();
                  }}
                />
              </div>
            ))}
          </fieldset>
          {formError && <p className="tournament-error" role="status">{formError}</p>}
          <button className="control" type="submit">Start tournament</button>
        </form>
      )}

      {controller.notice && <p className="tournament-notice" role="status">{controller.notice}</p>}
      <PastTournaments
        tournaments={controller.pastTournaments}
        storageAvailable={controller.storageAvailable}
      />
      <section className="tournament-exchange" aria-labelledby="tournament-json-heading">
        <h3 id="tournament-json-heading">Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          rows={8}
          spellCheck={false}
          value={tournamentJson}
          onChange={(event) => {
            setTournamentJson(event.currentTarget.value);
            controller.clearNotice();
          }}
        />
        <div className="tournament-actions">
          <button className="control" type="button" onClick={exportTournament}>Export tournament</button>
          <button className="control" type="button" onClick={loadTournament}>Load tournament</button>
        </div>
      </section>
    </section>
  );
}

interface LiveTournamentProps {
  tournament: Tournament;
  playerName: string;
  currentRound: string;
  startTurn(): void;
  activate(index: number): void;
  nextTurn(): void;
  nextMatch(): void;
  onBack(): void;
}

function LiveTournament(props: LiveTournamentProps) {
  const { tournament } = props;
  const winner = champion(tournament);
  const game = tournament.currentGame;
  return (
    <div className="tournament-live">
      {winner ? (
        <div className="tournament-champion">
          <h3>Champion: {winner.name}</h3>
          <button className="control" type="button" onClick={props.onBack}>Back to game</button>
        </div>
      ) : (
        <>
          <p className="tournament-round">Round: {props.currentRound}</p>
          <p className="tournament-now">Now playing: {props.playerName}</p>
          {tournament.phase === 'ready' && (
            <button className="control" type="button" onClick={props.startTurn}>Start turn</button>
          )}
          {tournament.phase === 'turnComplete' && (
            <button
              className="control"
              type="button"
              onClick={tournament.currentTurn === 0 ? props.nextTurn : props.nextMatch}
            >
              {tournament.currentTurn === 0 ? 'Next turn' : 'Next match'}
            </button>
          )}
          {game && (
            <>
              <GameStatus game={game} best={undefined} celebration={false} showBest={false} />
              <p id="tournament-board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or
                Space reveals a card.
              </p>
              <Board
                key={`${tournament.currentMatchIndex}-${tournament.currentTurn}`}
                game={game}
                activate={props.activate}
                ref={null as unknown as React.RefObject<BoardFocus | null>}
              />
            </>
          )}
        </>
      )}
      <Bracket tournament={tournament} />
    </div>
  );
}

interface PastTournamentsProps {
  tournaments: readonly Tournament[];
  storageAvailable: boolean;
}

function PastTournaments({ tournaments, storageAvailable }: PastTournamentsProps) {
  return (
    <section className="past-tournaments" aria-labelledby="past-tournaments-heading">
      <h3 id="past-tournaments-heading">Past tournaments</h3>
      {!storageAvailable && <p>Progress won't be saved on this device.</p>}
      {tournaments.length === 0 ? (
        <p>No completed tournaments.</p>
      ) : (
        <div className="past-tournament-list">
          {tournaments.map((tournament) => {
            const winner = champion(tournament);
            return (
              <details key={`${tournament.createdAt}-${tournament.matches[0]?.boardCode}`}>
                <summary>
                  Champion: {winner?.name ?? 'Unknown'} · {tournament.finishedAt}
                </summary>
                <Bracket tournament={tournament} label="Past tournament bracket" />
              </details>
            );
          })}
        </div>
      )}
    </section>
  );
}

