  3	import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
  4	import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
  5	import { isAcceptedTournamentName } from './names.ts';
  6	import { matchPlans } from './pairing.ts';
  7	import { winningSeed } from './rules.ts';
  8	import type { Entrant, Tournament, TournamentMatch, TournamentResult } from './rules.ts';
  9	
 10	const EVENT_KEYS = [
 11	  'kind', 'playerCount', 'players', 'matches', 'currentMatchIndex', 'currentTurn', 'phase',
 12	  'createdAt', 'finishedAt', 'gameSnapshot', 'gameElapsedMs',
 13	];
 14	const MATCH_KEYS = [
 15	  'round', 'number', 'size', 'boardCode', 'playerSeeds', 'results', 'winnerSeed', 'advanceTo',
 16	];
 17	
 18	export function serializeEvent(tournament: Tournament): Record<string, unknown> {
 19	  return {
 20	    kind: 'event',
 21	    playerCount: tournament.playerCount,
 22	    players: tournament.players,
 23	    matches: tournament.matches,
 24	    currentMatchIndex: tournament.currentMatchIndex,
 25	    currentTurn: tournament.currentTurn,
 26	    phase: tournament.phase,
 27	    createdAt: tournament.createdAt,
 28	    finishedAt: tournament.finishedAt,
 29	    gameSnapshot: tournament.currentGame ? encodeSnapshot(tournament.currentGame) : null,
 30	    gameElapsedMs: tournament.currentGame?.elapsedMs ?? null,
 31	  };
 32	}
 33	
 34	export function parseEvent(value: unknown): Tournament | null {
 35	  if (!isJsonObject(value) || !hasExactKeys(value, EVENT_KEYS) || value.kind !== 'event') return null;
 36	  const count = value.playerCount;
 37	  if (count !== 4 && count !== 8) return null;
 38	  const players = readPlayers(value.players, count);
 39	  const plans = matchPlans(count);
 40	  const matches = readMatches(value.matches, plans, count);
 41	  const currentMatchIndex = value.currentMatchIndex;
 42	  const currentTurn = value.currentTurn;
 43	  const phase = value.phase;
 44	  if (
 45	    !players || !matches || !isNonnegativeSafeInteger(currentMatchIndex) ||
 46	    currentMatchIndex >= matches.length || (currentTurn !== 0 && currentTurn !== 1) ||
 47	    !['ready', 'playing', 'turnComplete', 'finished'].includes(String(phase))
 48	  ) return null;
 49	  if (!isIsoDate(value.createdAt)) return null;
 50	  const finishedAt = value.finishedAt;
 51	  if (finishedAt !== null && !isIsoDate(finishedAt)) return null;
 52	  const bracket = validateBracket(matches, plans, count);
 53	  if (!bracket || !validProgress(matches, currentMatchIndex, currentTurn, phase, finishedAt)) return null;
 54	  const currentMatch = matches[currentMatchIndex];
 55	  if (!currentMatch) return null;
 56	  const currentGame = readCurrentGame(
 57	    value.gameSnapshot,
 58	    value.gameElapsedMs,
 59	    phase,
 60	    currentMatch,
 61	    matches[currentMatchIndex]?.results[currentTurn] ?? null,
 62	  );
 63	  if (currentGame === undefined) return null;
 64	  return {
 65	    playerCount: count,
 66	    players,
 67	    matches,
 68	    currentMatchIndex,
 69	    currentTurn,
 70	    phase,
 71	    currentGame,
 72	    createdAt: value.createdAt,
 73	    finishedAt,
 74	  };
 75	}
 76	
 77	function readPlayers(value: unknown, count: 4 | 8): Entrant[] | null {
 78	  if (!Array.isArray(value) || value.length !== count) return null;
 79	  const players: Entrant[] = [];
 80	  for (let index = 0; index < count; index += 1) {
 81	    const item: unknown = value[index];
 82	    if (!isJsonObject(item) || !hasExactKeys(item, ['seed', 'name'])) return null;
 83	    if (item.seed !== index + 1 || typeof item.name !== 'string' || !isAcceptedTournamentName(item.name))
 84	      return null;
 85	    players.push({ seed: item.seed, name: item.name });
 86	  }
 87	  return new Set(players.map((player) => player.name.toLowerCase())).size === count ? players : null;
 88	}
 89	
 90	function readResult(value: unknown, size: number): TournamentResult | null | undefined {
 91	  if (value === null) return null;
 92	  if (!isJsonObject(value) || !hasExactKeys(value, ['moves', 'elapsedMs'])) return undefined;
 93	  const { moves, elapsedMs } = value;
 94	  if (
 95	    !isNonnegativeSafeInteger(moves) || moves < (size * size) / 4 || moves > MOVES_MAX ||
 96	    typeof elapsedMs !== 'number' || !Number.isFinite(elapsedMs) ||
 97	    elapsedMs < 0 || elapsedMs > ELAPSED_MAX_MS
 98	  ) return undefined;
 99	  return { moves, elapsedMs };
100	}
101	
102	function readMatches(value: unknown, plans: ReturnType<typeof matchPlans>, count: 4 | 8): TournamentMatch[] | null {
103	  if (!Array.isArray(value) || value.length !== plans.length) return null;
104	  const usedCodes = new Set<string>();
105	  const matches: TournamentMatch[] = [];
106	  for (let index = 0; index < plans.length; index += 1) {
107	    const item: unknown = value[index];
108	    const plan = plans[index];
109	    if (!plan || !isJsonObject(item) || !hasExactKeys(item, MATCH_KEYS)) return null;
110	    const parsedCode = typeof item.boardCode === 'string' ? parseBoardCode(item.boardCode) : null;
111	    if (
112	      item.round !== plan.round || item.number !== plan.number || item.size !== plan.size ||
113	      !parsedCode || parsedCode.size !== plan.size || usedCodes.has(item.boardCode as string)
114	    ) return null;
115	    usedCodes.add(item.boardCode as string);
116	    if (!Array.isArray(item.playerSeeds) || item.playerSeeds.length !== 2 ||
117	        !Array.isArray(item.results) || item.results.length !== 2) return null;
118	    const playerSeeds = item.playerSeeds;
119	    if (!playerSeeds.every((seed) => seed === null || (isNonnegativeSafeInteger(seed) && seed > 0 && seed <= count)))
120	      return null;
121	    const first = readResult(item.results[0], plan.size);
122	    const second = readResult(item.results[1], plan.size);
123	    if (first === undefined || second === undefined) return null;
124	    const advanceTo = readAdvance(item.advanceTo, plan.advanceTo);
125	    const winnerSeed = item.winnerSeed;
126	    if (advanceTo === undefined ||
127	        !(winnerSeed === null || (isNonnegativeSafeInteger(winnerSeed) && winnerSeed > 0 && winnerSeed <= count)))
128	      return null;
129	    matches.push({
130	      ...plan,
131	      boardCode: item.boardCode as string,
132	      playerSeeds: [playerSeeds[0] as number | null, playerSeeds[1] as number | null],
133	      results: [first, second],
134	      winnerSeed,
135	      advanceTo,
136	    });
137	  }
138	  return matches;
139	}
140	
141	function readAdvance(
142	  value: unknown,
143	  expected: TournamentMatch['advanceTo'],
144	): TournamentMatch['advanceTo'] | undefined {
145	  if (expected === null) return value === null ? null : undefined;
146	  if (!isJsonObject(value) || !hasExactKeys(value, ['matchIndex', 'slot'])) return undefined;
147	  return value.matchIndex === expected.matchIndex && value.slot === expected.slot ? expected : undefined;
148	}
149	
150	function validateBracket(
151	  matches: readonly TournamentMatch[],
152	  plans: ReturnType<typeof matchPlans>,
153	  count: 4 | 8,
154	): boolean {
155	  const expectedSeeds = plans.map((plan) => [...plan.playerSeeds] as [number | null, number | null]);
156	  for (let index = 0; index < matches.length; index += 1) {
157	    const match = matches[index];
158	    const seeds = expectedSeeds[index];
159	    if (!match || !seeds || match.playerSeeds.some((seed, slot) => seed !== seeds[slot])) return false;
160	    const [first, second] = match.results;
161	    if (second && !first) return false;
162	    if (first && second) {
163	      const firstSeed = match.playerSeeds[0];
164	      const secondSeed = match.playerSeeds[1];
165	      if (firstSeed === null || secondSeed === null ||
166	          match.winnerSeed !== winningSeed(firstSeed, first, secondSeed, second)) return false;
167	      if (match.advanceTo) {
168	        const target = expectedSeeds[match.advanceTo.matchIndex];
169	        if (!target || target[match.advanceTo.slot] !== null) return false;
170	        target[match.advanceTo.slot] = match.winnerSeed;
171	      }
172	    } else if (match.winnerSeed !== null) return false;
173	  }
174	  return count === 4 || count === 8;
175	}
176	
177	function validProgress(
178	  matches: readonly TournamentMatch[],
179	  index: number,
180	  turn: 0 | 1,
181	  phase: unknown,
182	  finishedAt: unknown,
183	): boolean {
184	  const active = matches[index];
185	  if (!active) return false;
186	  for (let before = 0; before < index; before += 1)
187	    if (!complete(matches[before])) return false;
188	  for (let after = index + 1; after < matches.length; after += 1)
189	    if (matches[after]?.results.some(Boolean)) return false;
190	  const [first, second] = active.results;
191	  if (phase === 'finished') return index === matches.length - 1 && complete(active) && finishedAt !== null;
192	  if (finishedAt !== null) return false;
193	  if (phase === 'ready' || phase === 'playing')
194	    return turn === 0 ? !first && !second : !!first && !second;
195	  if (phase === 'turnComplete')
196	    return turn === 0 ? !!first && !second : !!first && !!second && index < matches.length - 1;
197	  return false;
198	}
199	
200	function complete(match: TournamentMatch | undefined): boolean {
201	  return !!match?.results[0] && !!match.results[1] && match.winnerSeed !== null;
202	}
203	
204	function readCurrentGame(
205	  snapshot: unknown,
206	  elapsedMs: unknown,
207	  phase: unknown,
208	  match: TournamentMatch,
209	  result: TournamentResult | null,
210	) {
211	  const hasGame = phase === 'playing' || phase === 'turnComplete';
212	  if (!hasGame) return snapshot === null && elapsedMs === null ? null : undefined;
213	  if (typeof snapshot !== 'string' || typeof elapsedMs !== 'number' ||
214	      !Number.isFinite(elapsedMs) || elapsedMs < 0 || elapsedMs > ELAPSED_MAX_MS) return undefined;
215	  const decoded = decodeSnapshot(snapshot);
216	  if (!decoded || decoded.boardCode !== match.boardCode || elapsedMs < decoded.elapsedMs ||
217	      elapsedMs >= decoded.elapsedMs + 1) return undefined;
218	  const game = { ...decoded, elapsedMs };
219	  if (phase === 'playing' && isWon(game)) return undefined;
220	  if (phase === 'turnComplete' && (!isWon(game) || !result || result.moves !== game.moves || result.elapsedMs !== game.elapsedMs))
221	    return undefined;
222	  return game;
223	}
224	
225	function isIsoDate(value: unknown): value is string {
226	  if (typeof value !== 'string') return false;
227	  const date = new Date(value);
228	  return Number.isFinite(date.getTime()) && date.toISOString() === value;
229	}

