              id={`tournament-player-${index + 1}`}
              className="control"
              type="text"
              autoComplete="off"
              value={name}
              onChange={(event) => changeName(index, event.currentTarget.value)}
            />
          </div>
        ))}
      </fieldset>
      {error && <p className="tournament-error" role="status">{error}</p>}
      <button className="control" type="submit">Start tournament</button>
    </form>
  );
}

