import { ELAPSED_MAX_MS, isWon } from '../game.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { hasExactKeys, isJsonObject, isNonnegativeSafeInteger } from '../saved-format.ts';
import { readMatches, readPlayers, validateBracket, validateProgress } from './event-shapes.ts';
import type { Tournament, TournamentMatch, TournamentPhase, TournamentResult } from './rules.ts';

const EVENT_KEYS = [
  'kind',
  'playerCount',
  'players',
  'matches',
  'currentMatchIndex',
  'currentTurn',
  'phase',
  'createdAt',
  'finishedAt',
  'gameSnapshot',
  'gameElapsedMs',
];

export function serializeEvent(tournament: Tournament): Record<string, unknown> {
  return {
    kind: 'event',
    playerCount: tournament.playerCount,
    players: tournament.players,
    matches: tournament.matches,
    currentMatchIndex: tournament.currentMatchIndex,
    currentTurn: tournament.currentTurn,
    phase: tournament.phase,
    createdAt: tournament.createdAt,
    finishedAt: tournament.finishedAt,
    gameSnapshot: tournament.currentGame ? encodeSnapshot(tournament.currentGame) : null,
    gameElapsedMs: tournament.currentGame?.elapsedMs ?? null,
  };
}

export function parseEvent(value: unknown): Tournament | null {
  if (!isJsonObject(value) || !hasExactKeys(value, EVENT_KEYS) || value.kind !== 'event')
    return null;
  const count = value.playerCount;
  if (count !== 4 && count !== 8) return null;
  const players = readPlayers(value.players, count);
  const matches = readMatches(value.matches, count);
  const index = value.currentMatchIndex;
  const turn = value.currentTurn;
  const phase = readPhase(value.phase);
  if (
    !players ||
    !matches ||
    !isNonnegativeSafeInteger(index) ||
    index >= matches.length ||
    (turn !== 0 && turn !== 1) ||
    !phase ||
    !isIsoDate(value.createdAt)
  )
    return null;
  const finishedAt = value.finishedAt;
  if (finishedAt !== null && !isIsoDate(finishedAt)) return null;
  if (
    !validateBracket(matches, count) ||
    !validateProgress(matches, index, turn, phase, finishedAt)
  )
    return null;
  const match = matches[index];
  if (!match) return null;
  const game = readCurrentGame(
    value.gameSnapshot,
    value.gameElapsedMs,
    phase,
    match,
    match.results[turn],
  );
  if (game === undefined) return null;
  return {
    playerCount: count,
    players,
    matches,
    currentMatchIndex: index,
    currentTurn: turn,
    phase,
    currentGame: game,
    createdAt: value.createdAt,
    finishedAt,
  };
}

function readCurrentGame(
  snapshot: unknown,
  elapsedMs: unknown,
  phase: TournamentPhase,
  match: TournamentMatch,
  result: TournamentResult | null,
) {
  if (phase !== 'playing' && phase !== 'turnComplete')
    return snapshot === null && elapsedMs === null ? null : undefined;
  if (
    typeof snapshot !== 'string' ||
    typeof elapsedMs !== 'number' ||
    !Number.isFinite(elapsedMs) ||
    elapsedMs < 0 ||
    elapsedMs > ELAPSED_MAX_MS
  )
    return undefined;
  const decoded = decodeSnapshot(snapshot);
  if (
    !decoded ||
    decoded.boardCode !== match.boardCode ||
    elapsedMs < decoded.elapsedMs ||
    elapsedMs >= decoded.elapsedMs + 1
  )
    return undefined;
  const game = { ...decoded, elapsedMs };
  if (phase === 'playing' && isWon(game)) return undefined;
  if (
    phase === 'turnComplete' &&
    (!isWon(game) || !result || result.moves !== game.moves || result.elapsedMs !== game.elapsedMs)
  )
    return undefined;
  return game;
}

function readPhase(value: unknown): TournamentPhase | null {
  return value === 'ready' ||
    value === 'playing' ||
    value === 'turnComplete' ||
    value === 'finished'
    ? value
    : null;
}

function isIsoDate(value: unknown): value is string {
  if (typeof value !== 'string') return false;
  const date = new Date(value);
  return Number.isFinite(date.getTime()) && date.toISOString() === value;
}
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { parseEvent, serializeEvent } from './event-format.ts';
import type { Tournament } from './rules.ts';

export const TOURNAMENTS_KEY = 'np3:tournaments';
export const TOURNAMENT_FILE_FORMAT = 'neon-pairs-tournament';
export const TOURNAMENT_FILE_VERSION = 1;
export const TOURNAMENT_HISTORY_LIMIT = 10;
export const TOURNAMENT_JSON_MAX_BYTES = 262_144;

export interface TournamentDraft {
  readonly playerCount: 4 | 8;
  readonly names: readonly string[];
}

export type TournamentLoad =
  | { readonly kind: 'setup'; readonly draft: TournamentDraft }
  | { readonly kind: 'event'; readonly tournament: Tournament };

export function encodeTournamentFile(
  tournament: Tournament | null,
  draft: TournamentDraft,
): string {
  const data = tournament ? serializeEvent(tournament) : serializeDraft(draft);
  return JSON.stringify(
    { format: TOURNAMENT_FILE_FORMAT, schemaVersion: TOURNAMENT_FILE_VERSION, data },
    null,
    2,
  );
}

export function decodeTournamentFile(text: string): TournamentLoad | null {
  if (!isWithinBytes(text, TOURNAMENT_JSON_MAX_BYTES)) return null;
  const value = parseJson(text);
  if (
    !isJsonObject(value) ||
    !hasExactKeys(value, ['format', 'schemaVersion', 'data']) ||
    value.format !== TOURNAMENT_FILE_FORMAT ||
    value.schemaVersion !== TOURNAMENT_FILE_VERSION ||
    !isJsonObject(value.data)
  )
    return null;
  if (value.data.kind === 'event') {
    const tournament = parseEvent(value.data);
    return tournament ? { kind: 'event', tournament } : null;
  }
  return readDraft(value.data);
